class SqlAlchemyInvoiceRepository:
    def __init__(self, session: Session) -> None:
        self._session = session                        # unit of work + identity map
    def get(self, invoice_id: int) -> Invoice | None:
        return self._session.get(Invoice, invoice_id)  # find by identity
    def find_overdue(self, on: date) -> Sequence[Invoice]:
        return self._session.scalars(                  # collection, not a query object
            select(Invoice).where(Invoice.due < on)
        ).all()
    def add(self, invoice: Invoice) -> None:
        self._session.add(invoice)                     # flush/commit: caller's unit of work

