@dataclass(frozen=True)
class Invoice:                              # domain object, no ORM base class
    id: int
    amount: Decimal
    due: date

    @classmethod
    def from_row(cls, row: sqlite3.Row) -> "Invoice":
        return cls(row["id"], row["amount"], date.fromisoformat(row["due"]))

def find_overdue(conn: sqlite3.Connection, on: date) -> list[Invoice]:
    cur = conn.execute("SELECT id, amount, due FROM invoice WHERE due < ?", (on.isoformat(),))
    return [Invoice.from_row(r) for r in cur.fetchall()]   # SQL confined to this module
